<section class="card attention"><h2><?= $v->e($v->t('needs_attention')) ?> <span class="count"><?= $data['needs_attention_total'] + $data['undelivered'] ?></span></h2><p><a href="/licences"><?= $v->e($v->t('undelivered')) ?>: <?= $v->e($data['undelivered']) ?></a></p><?= $v->table($data['undelivered_rows'],['jti','email','plan','created_at'],'/licences/') ?><?= $v->table($data['needs_attention'],['id','type','outcome','product_id','attempts'],'/events/') ?></section>
<div class="kpis">
